{
  "probability": 0.95,
  "range_low": 0.89,
  "range_high": 0.99,
  "summary": [
    "Early-2026 tolls suggest a high base rate for the Mediterranean route, with 524–606 deaths by February; March could push totals toward 900 if the pace remains elevated.",
    "Harsh sea conditions and ongoing crossings raise risk; however, SAR capacity changes and reporting lags inject uncertainty about the March total.",
    "Calibrated update yields a 95% posterior probability that 900 deaths will be reached before April 2026 given current signals."
  ],
  "confidence": "high",
  "narrative": "As of February 2026, around 524–606 deaths were recorded, implying that a sharp March could push the total to or beyond 900 by end-March if mortality remains elevated. While deteriorating weather and policy shifts support higher tolls, SAR constraints and reporting lags keep some upside and downside risk, resulting in a high-calibration posterior around 0.95.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class: IOM Missing Migrants Project Central/Western Mediterranean deaths; anchored on 2014–2025 annual totals with 2026 early-month counts (Feb) as base-rate anchor."
    },
    "factor_updates": [
      {
        "factor": "March 2026 mortality pace",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "February tolls around 524–606 imply that if March maintains an elevated pace, the cumulative toll could reach or exceed 900 by end-March."
      },
      {
        "factor": "March 2026 sea/weather severity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Continued harsh seas increase likelihood of shipwrecks and fatalities, contributing to a high March toll."
      },
      {
        "factor": "Search-and-rescue capacity/policy changes",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR or stricter policies could reduce deaths and slow accumulation toward 900."
      },
      {
        "factor": "Data reporting lags or revisions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Tallies may be revised; timing could shift counts modestly, adding uncertainty."
      }
    ],
    "synthesis_rationale": "The posterior likelihood is derived by starting from the base-rate anchor (0.65) and applying modest-to-moderate upward updates for a high March mortality pace and harsh sea conditions, tempered by potential reductions from SAR improvements and minor data lags. The combined, somewhat correlated factors yield a high-calibration posterior of about 0.95, with a plausible 0.89–0.99 range and caveats around weather, policy, and reporting."
  }
}

{
  "probability": 0.95,
  "range_low": 0.85,
  "range_high": 0.99,
  "summary": [
    "Early-2026 toll: approximately 524–606 deaths by February, implying a high but not guaranteed path to 900 by end-March if the March mortality pace stays elevated.",
    "Severe winter weather and high-sea conditions raise the likelihood of further fatalities, supporting a higher near-term total.",
    "Policy/SAR capacity dynamics and reporting lags introduce uncertainty; while they can push totals up (e.g., weaker SAR) they can also dampen counts if measures improve."
  ],
  "confidence": "high",
  "narrative": "Observed early-2026 Mediterranean deaths are already in the hundreds. If March remains comparably deadly and SAR capacity remains strained, a 900-toll by end-March is plausible but not certain; incorporating base-rate and weather/policy factors yields a calibrated 95% posterior with some residual uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Chosen anchor from forecast evidence using the IOM Mediterranean annual-death baseline (roughly 2,000–2,800 per year) and early-2026 counts (~524–606 by February) to establish a mid-to-high starting point."
    },
    "factor_updates": [
      {
        "factor": "March 2026 mortality pace",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "February toll implies March could push totals toward 900 if the high mortality pace persists."
      },
      {
        "factor": "March 2026 sea/weather severity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Harsh seas and winter storms increase risk of shipwrecks and fatalities, raising monthly totals."
      },
      {
        "factor": "Funding cuts reducing search-and-rescue capacity and casualty reporting",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Diminished SAR capacity and underfunded reporting can elevate deaths and slow reporting, boosting near-term totals."
      },
      {
        "factor": "Policy/regulatory responses—unclear impact on crossing dynamics",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Tighter controls may reduce crossings or shift risk; near-term effect on March toll uncertain."
      }
    ],
    "synthesis_rationale": "Starting from a base anchor around 0.65 from forecast evidence, we added factors with positive updates for pace, weather, and SAR constraints, tempered by potential policy effects and data lags. The correlated nature of weather and SAR conditions risks double-counting in update magnitudes; calibration yields a 95% posterior with range reflecting remaining uncertainty (range_low 0.85 to range_high 0.99)."
  }
}

